mapper.select:
select r.* from chatroom r join chatRoomJoin j
	on r.roomNo = j.roomNo
	where j.userid = #{userid}

mapper.update:
update chatRoomJoin 
	set lastReadMsgNo = (select NVL(MAX(msgNo), 0) from chatMessage where roomNo = #{roomNo}) 
	where roomNo = #{roomNo} and userid = #{userid}

mapper.select:
select MAX(msgNo) from chatMessage 
	where roomNo = #{roomNo} 
	and senderId = #{senderId}
